            if (target > 0.5) {
                loss = -z + std::log1p(e);
            } else {
                loss = std::log1p(e);
            }
        }

        loss_sum += loss * inv_n;

        double delta = (p - target) * inv_n;
        grad[b2_off] += delta;

        for (int j = 0; j < n_hidden; ++j) {
            double a = b1[j];
            const double* w1j = W1 + j * n_in;
